#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int countWords(const string& s) {
    int words = 0;
    bool inWord = false;
    for (char c : s) {
        if (c == ' ') {
            inWord = false;
        } else {
            if (!inWord) words++;
            inWord = true;
        }
    }
    return words;
}

